using HakutaiKagami.Core.Contracts;
using HakutaiKagami.Core.Messaging;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class StandingAdministrationTests
{
 static readonly EntityId Owner=new("org:oda"),Site=new("site:castle"),Person=HouseholdCourtTests.Retainer;
 static void Good(CommandResult r)=>Assert.True(r.Code==ResultCode.Accepted,r.VisibleReason);
 internal static WorldSession Appointed(){var s=HouseholdCourtTests.Start();Good(s.ManageCourt(new(new("request:administration-office"),CourtAction.Nominate,Person,Owner,Site),s.Revision));return s;}
 static AdministrationInput Terms(WorldSession s,long coins=100)=>new(new("request:admin-terms/"+s.Revision),AdministrationAction.IssueTerms,Owner,Site,Person,AnnualCoins:coins);
 internal static WorldSession Granted(){var s=Appointed();Good(s.ManageAdministration(Terms(s),s.Revision));NewGameWorldTests.At(s,3);return s;}
 [Fact]public void AnnualTermsHaveNoEffectBeforeActualReceiptAndAcceptance(){var s=Appointed();var i=Terms(s);Good(s.ManageAdministration(i,s.Revision));Assert.Null(StandingAdministration.Grant(s.DiagnosticSnapshot(),Person,Site,s.Seconds,s.Revision+1));Assert.False(StandingAdministration.Inbox(s.DiagnosticSnapshot(),Person).Any());NewGameWorldTests.At(s,3);Assert.NotNull(StandingAdministration.Grant(s.DiagnosticSnapshot(),Person,Site,s.Seconds,s.Revision+1));Assert.Contains(s.DiagnosticSnapshot().Administration!.Events,e=>e.Input.Action==AdministrationAction.AcceptTerms&&e.Actor==Person);}
 [Fact]public void StewardBuildsWithinAnnualBudgetAndLeavesPrivateMoneyUntouched(){var s=Granted();long money=NewGameWork.Balance(s.DiagnosticSnapshot(),Person);NewGameWorldTests.At(s,8*86400);var projects=s.DiagnosticSnapshot().PublicWorks!.Orders.Where(q=>q.Actor==Person).ToArray();Assert.Equal(2,projects.Length);Assert.Equal(100,projects.Sum(q=>q.Coins));Assert.Equal(0,StandingAdministration.Remaining(s.DiagnosticSnapshot(),Person,Site));Assert.Equal(money+SocialWorld.Net(s.DiagnosticSnapshot(),NewGameWork.Wallet(Person)),NewGameWork.Balance(s.DiagnosticSnapshot(),Person));}
 [Fact]public void StandingOfficeAloneCannotSpendUnboundedConstructionResources(){var s=Appointed();var w=s.DiagnosticSnapshot();Assert.Throws<InvalidDataException>(()=>PublicWorks.Execute(w,new(new("request:unfunded-steward-work"),Site,WorksKind.Agriculture),Person));}
 [Fact]public void OnlyARealCouncilMayAdoptHousePolicy(){var s=Appointed();Assert.Equal(ResultCode.NotAvailable,s.ManageAdministration(new(new("request:no-council-policy"),AdministrationAction.SetPolicy,Owner,Site,s.PlayerControl,Policy:HousePolicy.Conserve),s.Revision).Code);}
 [Fact]public void PolicyIsUnknownUntilTheMemberActuallyReceivesAndOpensIt(){var t=HouseholdCourtTests.Council();var s=t.Session;var held=s.DiagnosticSnapshot().Court!.Events.Last(e=>e.Input.Action==CourtAction.HoldCouncil);Good(s.ManageAdministration(new(new("request:council-policy"),AdministrationAction.SetPolicy,Owner,Site,s.PlayerControl,held.Input.Id,Policy:HousePolicy.Conserve),s.Revision));Assert.Equal(HousePolicy.Conserve,StandingAdministration.KnownPolicy(s.DiagnosticSnapshot(),s.PlayerControl,Owner));Assert.Equal(HousePolicy.Balanced,StandingAdministration.KnownPolicy(s.DiagnosticSnapshot(),Person,Owner));NewGameWorldTests.At(s,s.Seconds+3);Assert.Equal(HousePolicy.Conserve,StandingAdministration.KnownPolicy(s.DiagnosticSnapshot(),Person,Owner));}
 [Fact]public void MonthlyReportRemainsSealedUntilHeadOpensIt(){var s=Granted();NewGameWorldTests.At(s,32*86400);var report=s.DiagnosticSnapshot().Administration!.Papers.Last(p=>p.Type=="report");Assert.DoesNotContain(StandingAdministration.KnownPapers(s.DiagnosticSnapshot(),s.PlayerControl),p=>p.Id==report.Id);Good(s.Open(s.PlayerControl,new(report.Id),s.Revision));Assert.Contains(StandingAdministration.KnownPapers(s.DiagnosticSnapshot(),s.PlayerControl),p=>p.Id==report.Id);}
 [Fact]public void RealSaveBeforeMonthlyBoundaryHasSameProjectsReportsAndResourceFuture(){var s=Granted();NewGameWorldTests.At(s,30*86400);s.SetPaused(true);var w=s.DiagnosticSnapshot();var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"standing-admin-"+Guid.NewGuid().ToString("N")),w.Definitions);Assert.True(store.Save(s,"mid",w.WorldId).Published);var host=new WorldSessionHost(Appointed());Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("mid"),host.Current,host.Current.Revision));foreach(var x in new[]{s,host.Current})NewGameWorldTests.At(x,32*86400);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(host.Current.DiagnosticSnapshot()));}
 [Fact]public void OldSaveRemainsExactAndEmptyAdministrationIsRejected(){var w=Appointed().DiagnosticSnapshot();var b=ContractJson.Write(w);Assert.Equal(b,ContractJson.Write(new WorldSession(ContractJson.Read<ContractWorld>(b)).DiagnosticSnapshot()));w.Administration=new(1,StandingAdministration.Policy,[],[]);Assert.Throws<InvalidDataException>(()=>new WorldSession(w));}

 static void Npc(WorldSession s,Action<ContractWorld> action)=>typeof(WorldSession).GetMethod("Change",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance)!.Invoke(s,[action,null]);
 [Fact]public void NpcHeadUsesActualMonthlyCouncilAndSendsItsChosenPolicy(){var s=HouseholdCourtTests.Start(HouseholdCourtTests.Ronin.Value);Npc(s,w=>HouseholdCourt.Execute(w,new(new("request:npc-admin-office"),CourtAction.Nominate,Person,Owner,Site),new("person:nobunaga")));Npc(s,w=>StandingAdministration.Execute(w,new(new("request:npc-admin-terms"),AdministrationAction.IssueTerms,Owner,Site,Person,AnnualCoins:50),new("person:nobunaga")));NewGameWorldTests.At(s,3700);var w=s.DiagnosticSnapshot();Assert.Contains(w.Court!.Events,e=>e.Input.Action==CourtAction.HoldCouncil&&e.Actor==new EntityId("person:nobunaga")&&e.Input.People!.Contains(Person));Assert.Contains(w.Administration!.Events,e=>e.Input.Action==AdministrationAction.SetPolicy&&e.Actor==new EntityId("person:nobunaga"));}
 [Fact]public void HarvestSeasonAndOfficeRevocationPreventFurtherDelegatedWork(){var s=Granted();var w=s.DiagnosticSnapshot();var date=new DateOnly(1560,9,1);long at=(date.DayNumber-new DateOnly(1560,1,1).DayNumber)*86400L;Assert.False((bool)typeof(StandingAdministration).GetMethod("WorkAllowed",System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.NonPublic)!.Invoke(null,[w,Person,Site,50L,at,w.CommitSequence+1])!);NewGameWorldTests.At(s,4);Good(s.ManageCourt(new(new("request:admin-revoke"),CourtAction.RevokeOffice,Person,Owner,Site,Reference:new("request:administration-office")),s.Revision));Assert.Null(StandingAdministration.Grant(s.DiagnosticSnapshot(),Person,Site,s.Seconds,s.Revision+1));}
 [Fact]public void EarlierConstructionWithoutAnnualTermsIsNotSilentlyReinterpreted(){var s=PublicWorksTests.Start();var r=s.StartPublicWork(new(new("request:prior-construction"),Site,WorksKind.Agriculture),s.Revision);Good(r);var w=s.DiagnosticSnapshot();w.PublicWorks=w.PublicWorks! with{Orders=w.PublicWorks.Orders.Select(q=>q with{AuthorizationPolicy=null}).ToArray()};var bytes=ContractJson.Write(w);Assert.Equal(bytes,ContractJson.Write(new WorldSession(ContractJson.Read<ContractWorld>(bytes)).DiagnosticSnapshot()));}
}
